// Extract the fields we need for triage from the raw email item
const item = $input.first().json;

const fromAddress = (item.from && item.from.value && item.from.value[0] && item.from.value[0].address) || item.from || '';
const subject = item.subject || '';
const textBody = item.text || item.textPlain || '';
const snippet = textBody.substring(0, 300);

return [{
  json: {
    fromAddress: String(fromAddress).toLowerCase(),
    subject,
    snippet,
    receivedDate: item.date || new Date().toISOString()
  }
}];

// Rule-based classification
const clientDomains = ($env.KNOWN_CLIENT_DOMAINS || '').split(',').map(d => d.trim().toLowerCase()).filter(Boolean);
const urgentKeywords = ($env.URGENT_KEYWORDS || 'urgent,deadline,hmrc investigation').split(',').map(k => k.trim().toLowerCase()).filter(Boolean);

const item = $input.first().json;
const subjectLower = item.subject.toLowerCase();
const snippetLower = item.snippet.toLowerCase();
const senderDomain = (item.fromAddress.split('@')[1] || '');

let category = 'Uncategorised';
if (subjectLower.includes('hmrc') || subjectLower.includes('companies house')) {
  category = 'Statutory';
} else if (subjectLower.includes('invoice') || subjectLower.includes('payment')) {
  category = 'Billing';
} else if (clientDomains.includes(senderDomain)) {
  category = 'Client Query';
}

const isUrgent = urgentKeywords.some(k => subjectLower.includes(k) || snippetLower.includes(k));

return [{
  json: {
    ...item,
    category,
    isUrgent
  }
}];

